import{_ as b,l as i,o as t,c as n,v as e,p as o,x as r,d as s,i as h,S as l}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"等价鞅测度","description":"","frontmatter":{"title":"等价鞅测度","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/equivalent-martingale-measure.md","filePath":"econ/equivalent-martingale-measure.md","lastUpdated":1789023840000}'),p={name:"econ/equivalent-martingale-measure.md"};function d(c,a,_,u,Q,P){const m=i("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="等价鞅测度" tabindex="-1">等价鞅测度 <a class="header-anchor" href="#等价鞅测度" aria-label="Permalink to &quot;等价鞅测度&quot;">​</a></h1><div class="epigraph"><p>换一套与原来等价的概率，折现资产价格变成鞅：定价是取期望，不是改偏好。</p><footer>—— 据 Harrison and Kreps, JET 1979；Harrison and Pliska, Stochastic Processes and their Applications, 1981</footer></div><p><a href="/econ/ftap">上一课</a>给出存在性：NA ⇔ 有一个（或一凸集）定价核。本课缺口是把核写成<strong>概率</strong> \\(\\mathbb{Q}\\)：在 \\(\\mathbb{Q}\\) 下，用计价账户折现后的价格过程是鞅。不重做分离超平面，不把 \\(\\mathbb{Q}\\) 说成市场上真有一群风险中性的人。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态价格 \\(q_s\\) 归一化成 \\(\\mathbb{Q}(s)=q_s/\\sum q\\)，一期定价变成 \\(p=B^{-1}\\mathrm{E}^{\\mathbb{Q}}[x]\\)。多期需要过程：选一个严格正的计价账户 \\(B\\)（通常是货币市场），要求 \\(S/B\\) 在 \\(\\mathbb{Q}\\) 下是鞅，即 \\(\\mathrm{E}^{\\mathbb{Q}}[S_{t+1}/B_{t+1}\\mid\\mathcal{F}_t]=S_t/B_t\\)。等价：\\(\\mathbb{Q}\\sim\\mathbb{P}\\)，同一零测集——否则某个 \\(\\mathbb{P}\\) 下可能发生的状态在定价里被抹掉，与 \\(q\\gg 0\\) 冲突。</p><p>缺口是记账：同一线性泛函，可以叫 \\(m\\)、可以叫 \\(q\\)、可以叫 \\(\\mathbb{Q}\\)。换名不是换理论。<a href="/econ/stochastic-discount-factor">SDF</a> 的 \\(m\\) 与密度过程满足 \\(m_{t,t+1}=(B_t/B_{t+1})(Z_{t+1}/Z_t)\\)，\\(Z\\) 为 \\(\\mathrm{d}\\mathbb{Q}/\\mathrm{d}\\mathbb{P}\\) 的密度。本课钉 \\(\\mathbb{Q}\\) 这一端。</p><p><span class="marginnote">「风险中性测度」是俗称：\\(\\mathbb{Q}\\) 下投资者像风险中性那样用 \\(B\\) 折现，并不意味着 \\(\\mathbb{P}\\) 下的人风险中性。风险厌恶被写进 \\(\\mathbb{P}\\mapsto\\mathbb{Q}\\) 的倾斜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>有限树：在每个节点解局部正价格，归一成条件概率，再拼成 \\(\\mathbb{Q}\\)。布朗模型：Girsanov 把漂移从 \\(\\mu\\) 扭到 \\(r\\)，波动不变；市场完全时扭法唯一，不完全时扭法有一整族（未定权益对应的风险市场价格自由）。计价账户可换：用某交易资产当 numéraire，得到另一套等价鞅——价格比对该 numéraire 是鞅。换 numéraire 不改变可复制权益的价格，改变的是计算便利。</p>',9)),(t(),o(l,null,{default:r(()=>[h(m,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NA%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%22%5D%20--%3E%20Q%5B%22Q%20~%20P%22%5D%0A%20%20Q%20--%3E%20MG%5B%22S%2FB%20%E6%98%AF%20Q-%E9%9E%85%22%5D%0A%20%20MG%20--%3E%20PR%5B%22p%20%3D%20E%5EQ%20%5B%E6%94%AF%E4%BB%98%20%2F%20B%5D%22%5D%0A%20%20M%5B%22SDF%20m%22%5D%20--%3E%20PR%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>不要把 Girsanov 写成「估计漂移」。\\(\\mu\\) 在 \\(\\mathbb{P}\\) 下是真实期望，定价不需要它——这正是对冲定价的要点。均衡要 \\(\\mu\\)，因为 \\(m\\) 来自消费；FTAP 只要 \\(\\mathbb{Q}\\)。后文 Lucas 树会把两者焊回同一 \\(m\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是改变概率权重：倒霉状态在 \\(\\mathbb{Q}\\) 下更重，等价于 \\(\\mathbb{P}\\) 下 \\(m\\) 更大。鞅的意思是：用 \\(\\mathbb{Q}\\) 看，任何可交易资产在补偿计价增长之后没有超额；有超额的方向会被复制成套利。动态就是把这句话放进每个条件信息集——与 <a href="/econ/emh">EMH</a> 的「经风险调整后不可预测」同构，FTAP 提供调整所用的测度。</p><p>不完全：许多 \\(\\mathbb{Q}\\) 都让可交易的 \\(S/B\\) 成为鞅，但对不可复制的 \\(x\\)，\\(\\mathrm{E}^{\\mathbb{Q}}[x/B]\\) 随 \\(\\mathbb{Q}\\) 变，故无唯一价格。这不是市场无效，是张成不足，接 <a href="/econ/incomplete-markets-gei">不完全市场</a> 的精神。</p><p><span class="marginnote">等价不允许把 \\(\\mathbb{P}\\) 的零事件标成正概率。那样会给不可能的状态定价，或把可能的状态标成套利。奇异性是定价失败，不是「另一种信念」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入随机利率下的远期测度细节，后文期限结构会按需取 numéraire。也不要把 \\(\\mathbb{Q}\\) 估计成历史频率——历史是 \\(\\mathbb{P}\\)。下一课问动态完备：多少资产、怎样再交易，才能让 \\(\\mathbb{Q}\\) 唯一、复制可行。</p><p>后课默认：EMM 是与 \\(\\mathbb{P}\\) 等价、使 \\(S/B\\) 为鞅的概率。定价是 \\(\\mathbb{Q}\\)–期望。\\(m\\) 与 \\(\\mathbb{Q}\\) 是同一泛函的两个写法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>等价：同一零测集；鞅：折现价格无 \\(\\mathbb{Q}\\)–超额。</li><li>风险厌恶在 \\(\\mathbb{P}\\to\\mathbb{Q}\\) 的倾斜里，不在「市场上有风险中性的人」。</li><li>完全则 \\(\\mathbb{Q}\\) 唯一；不完全则价格区间。</li><li>出处：Harrison and Kreps, <em>JET</em> 1979；Harrison and Pliska, 1981。</li></ul>',10))])}const E=b(p,[["render",d]]);export{B as __pageData,E as default};
